package com.example.bookmyticket.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="bookings")
public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String bookingCode; @Column(nullable=false) private String customerName; @Column(nullable=false) private String email; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="show_id") private MovieShow movieShow; @Column(nullable=false,precision=10,scale=2) private BigDecimal totalAmount; @Column(nullable=false) private LocalDateTime bookedAt; public Booking(){} public Booking(String c,String n,String e,MovieShow s,BigDecimal a,LocalDateTime d){bookingCode=c;customerName=n;email=e;movieShow=s;totalAmount=a;bookedAt=d;} public Long getId(){return id;} public String getBookingCode(){return bookingCode;} public String getCustomerName(){return customerName;} public String getEmail(){return email;} public MovieShow getMovieShow(){return movieShow;} public BigDecimal getTotalAmount(){return totalAmount;} public LocalDateTime getBookedAt(){return bookedAt;} }
